<?php# protect against hack attemptsif (!defined('NGCMS'))die ('Galaxy in danger');function plugin_football_stats_install($action) {	global $lang, $mysql, $config;		if ($action != 'autoapply')		LoadPluginLang('football_stats', 'config', '', 'fs', ':');			$db_create = array(		array(			'table' => 'football_countries',			'action' => 'cmodify',			'key' => 'primary key (`id`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'name', 'type' => 'varchar(255)', 'params' => 'UNIQUE NOT NULL'),				array('action' => 'cmodify', 'name' => 'alias', 'type' => 'varchar(100)', 'params' => 'UNIQUE NOT NULL'),			)		),		array(			'table' => 'football_teams',			'action' => 'cmodify',			'key' => 'primary key (`id`), key `type` (`type`), key `uefa_rating` (`uefa_rating`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'type', 'type' => 'TINYINT', 'params' => 'DEFAULT 0'),				array('action' => 'cmodify', 'name' => 'name', 'type' => 'varchar(255)', 'params' => 'UNIQUE NOT NULL'),				array('action' => 'cmodify', 'name' => 'alias', 'type' => 'varchar(100)', 'params' => 'UNIQUE NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_country', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'photo', 'type' => 'varchar(100)'),				array('action' => 'cmodify', 'name' => 'description', 'type' => 'text'),				array('action' => 'cmodify', 'name' => 'uefa_position', 'type' => 'smallint', 'params' => 'DEFAULT NULL'),				array('action' => 'cmodify', 'name' => 'uefa_rating', 'type' => 'float', 'params' => 'DEFAULT NULL'),			)		),		array(			'table' => 'football_championats',			'action' => 'cmodify',			'key' => 'primary key (id), key `type` (`type`), key `typeStart` (`type`, `start`), key `typeStartFinish` (`type`, `start`, `finish`), key `id_country` (`id_country`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'id_country', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'name', 'type' => 'varchar(255)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'start', 'type' => 'SMALLINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'finish', 'type' => 'SMALLINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'type', 'type' => 'TINYINT', 'params' => 'DEFAULT 0'),				array('action' => 'cmodify', 'name' => 'add_type', 'type' => 'TINYINT', 'params' => 'DEFAULT 0'),			)		),				array(			'table' => 'football_teams_championats',			'action' => 'cmodify',			'key' => 'primary key (id_championat, id_team), key `id_championat` (`id_championat`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id_championat', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'fine', 'type' => 'TINYINT', 'params' => 'NOT NULL'),			)		),				array(			'table' => 'football_games',			'action' => 'cmodify',			'key' => 'primary key (id), key `id_championat` (`id_championat`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'id_championat', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'round', 'type' => 'TINYINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team_guest', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team_owner', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'goals_guest', 'type' => 'TINYINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'goals_owner', 'type' => 'TINYINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'photo', 'type' => 'varchar(255)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'video', 'type' => 'varchar(255)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'stats', 'type' => 'varchar(255)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'date', 'type' => 'datetime', 'params' => ''),				array('action' => 'cmodify', 'name' => 'channel', 'type' => 'varchar(50)', 'params' => ''),				array('action' => 'cmodify', 'name' => 'reds_owner', 'type' => 'TINYINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'reds_guest', 'type' => 'TINYINT', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'status', 'type' => 'TINYINT', 'params' => 'NOT NULL')			)		),				array(			'table' => 'football_players',			'action' => 'cmodify',			'key' => 'primary key (id), key `id_team` (`id_team`), key `id_team_country` (`id_team_country`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'name', 'type' => 'varchar(255)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team_country', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'bio', 'type' => 'text')			)		),				array(			'table' => 'football_games_goals',			'action' => 'cmodify',			'key' => 'primary key (id), key `gameTeam` (`id_game`, `id_team`), key `championatPlayer` (`id_championat`, `id_player`)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'id_championat', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_game', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_team', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'id_player', 'type' => 'int(10)', 'params' => 'NOT NULL'),				array('action' => 'cmodify', 'name' => 'minute', 'type' => 'TINYINT', 'params' => 'UNSIGNED NOT NULL'),				array('action' => 'cmodify', 'name' => 'auto', 'type' => 'TINYINT', 'params' => 'DEFAULT 0'),			)		),				array(			'table' => 'football_leagues',			'action' => 'cmodify',			'key' => 'primary key (id)',			'fields' => array(				array('action' => 'cmodify', 'name' => 'id', 'type' => 'int(10)', 'params' => 'UNSIGNED NOT NULL AUTO_INCREMENT'),				array('action' => 'cmodify', 'name' => 'name', 'type' => 'varchar(50)', 'params' => 'UNIQUE NOT NULL'),				array('action' => 'cmodify', 'name' => 'alias', 'type' => 'varchar(50)', 'params' => 'UNIQUE NOT NULL'),				array('action' => 'cmodify', 'name' => 'type', 'type' => 'TINYINT', 'params' => 'DEFAULT 0'),			)		),	);		switch ($action) {		case 'confirm': 			 generate_install_page('football_stats', $lang['fs:install_msg']);			 break;		case 'autoapply':		case 'apply':			if (fixdb_plugin_install('football_stats', $db_create, 'install', ($action=='autoapply')?true:false)) {							pluginSetVariable('football_stats', 'pagination', 10);				pluginsSaveConfig();								$ULIB = new urlLibrary();				$ULIB->loadConfig();							$ULIB->registerCommand('football_stats', 'football',						array ('vars' => array(							'name' => array(							'matchRegex' => '.+?', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_football']							)							),						),						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_football_d']),						)				);				$ULIB->registerCommand('football_stats', 'team',						array ('vars' => array(							'name' => array(							'matchRegex' => '.+?', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_team']							)							),						),						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_team_d']),						)				);								$ULIB->registerCommand('football_stats', 'player',						array ('vars' => array(							'id' => array(							'matchRegex' => '\\d+', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_player']							)							),						),						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_player_d']),						)				);								$ULIB->registerCommand('football_stats', 'match',						array ('vars' => array(							'id' => array(							'matchRegex' => '\\d+', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_match']							)							),						),						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_match_d']),						)				);								$ULIB->registerCommand('football_stats', 'league',						array ('vars' => array(							'year_start' => array(							'matchRegex' => '\\d{4}', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_league_start']							)							),							'year_end' => array(							'matchRegex' => '\\d{4}', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_league_end']							)							),							'type' => array(							'matchRegex' => '.+?', 							'descr' => array(								$config['default_lang'] => $lang['fs:ULIB_league_type']							)							),						),						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_league_d']),						)				);								$ULIB->registerCommand('football_stats', 'uefa_team',						array (						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_uefa_team_d']),						)				);								$ULIB->registerCommand('football_stats', 'uefa_country',						array (						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_uefa_country_d']),						)				);				$ULIB->registerCommand('football_stats', 'fifa_country',						array (						'descr'	=> array ($config['default_lang'] => $lang['fs:ULIB_fifa_country_d']),						)				);				$ULIB->saveConfig();								plugin_mark_installed('football_stats');			} else {				return false;			}			break;	}	return true;}